const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const form=document.querySelector('form'),steps=[...form.querySelectorAll('fieldset')],next=form.querySelector('.next'),back=form.querySelector('.back'),submit=form.querySelector('.submit'),message=document.querySelector('#form-message');let step=0;
const seccional=form.elements.namedItem('Seccional');'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ').forEach(s=>seccional.add(new Option(s,s)));
const cpf=form.elements.namedItem('CPF');cpf.addEventListener('input',()=>{const n=cpf.value.replace(/\D/g,'').slice(0,11);cpf.value=n.replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2')});
form.elements.namedItem('Data de nascimento').max=new Date().toISOString().slice(0,10);
function renderReview(){const review=document.querySelector('#review-data');review.replaceChildren();for(const label of ['Nome completo','E-mail','OAB','Seccional']){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=form.elements.namedItem(label).value||'Não preenchido nesta demonstração';row.append(dt,dd);review.append(row)}for(const input of form.querySelectorAll('input[type=file]')){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=input.name;dd.textContent=[...input.files].map(f=>f.name).join(', ')||'Não anexado nesta demonstração';row.append(dt,dd);review.append(row)}}
function show(){const last=steps.length-1;steps.forEach((s,i)=>s.hidden=i!==step);next.hidden=step===last;submit.hidden=step!==last;back.hidden=step===0;document.querySelector('#stepcount').textContent=`0${step+1} / 0${steps.length}`;document.querySelector('.progress i').style.width=`${(step+1)*100/steps.length}%`;document.querySelectorAll('.flow-labels li').forEach((li,i)=>{li.classList.toggle('active',i===step);if(i===step)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current')});message.textContent='';next.textContent=step===2?'Seguir para anexar comprovante':step===3?'Revisar solicitação':'Continuar';const arrow=document.createElementNS('http://www.w3.org/2000/svg','svg');arrow.setAttribute('class','arrow-icon');arrow.setAttribute('viewBox','0 0 24 24');arrow.setAttribute('fill','none');arrow.setAttribute('stroke','currentColor');arrow.setAttribute('stroke-width','1.6');arrow.setAttribute('stroke-linecap','round');arrow.setAttribute('stroke-linejoin','round');arrow.setAttribute('aria-hidden','true');arrow.setAttribute('focusable','false');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M4 12h16M13 5l7 7-7 7');arrow.append(path);next.append(arrow);if(step===last)renderReview();const legend=steps[step].querySelector('legend');legend.tabIndex=-1;legend.focus({preventScroll:true});document.querySelector('.form-wrap').scrollIntoView({block:'start',behavior:'smooth'})}
next.onclick=()=>{if(step<steps.length-1){step++;show()}};back.onclick=()=>{if(step>0){step--;show()}};
form.querySelectorAll('input[type=file]').forEach(input=>input.addEventListener('change',()=>{input.setCustomValidity('');for(const file of input.files){if(file.size>5*1024*1024||!(/\.(pdf|jpe?g|png)$/i.test(file.name))){input.setCustomValidity('Escolha arquivos PDF, JPG ou PNG de até 5 MB.');input.reportValidity();break}}}));
form.addEventListener('submit',event=>{event.preventDefault();message.textContent='Demonstração concluída. Nenhum dado ou arquivo foi enviado. O recebimento por e-mail e as instruções Pix ainda precisam ser configurados pela associação.';submit.disabled=true;submit.textContent='Simulação concluída ✓';message.scrollIntoView({block:'center',behavior:'smooth'})});
form.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName==='INPUT'&&step<steps.length-1){e.preventDefault();next.click()}});

// Preencher somente com os dados de pagamento confirmados pela associação.
const pix={key:'',recipient:'',amount:''};
if(pix.key&&pix.recipient){document.querySelector('#pix-key').value=pix.key;document.querySelector('#pix-recipient').textContent=pix.recipient;document.querySelector('#pix-amount').textContent=pix.amount||'Consulte a associação';const copyPix=document.querySelector('#copy-pix');copyPix.disabled=false;document.querySelector('#pix-status').textContent='Copie a chave e faça o pagamento no aplicativo do seu banco.';copyPix.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(pix.key);document.querySelector('#pix-status').textContent='Chave Pix copiada.'}catch{document.querySelector('#pix-key').select();document.querySelector('#pix-status').textContent='Selecione e copie a chave acima.'}})}

document.querySelectorAll('.flow-labels li')[0].classList.add('active');document.querySelectorAll('.flow-labels li')[0].setAttribute('aria-current','step');

const photoDialog=document.querySelector('#photo-dialog'),photoLarge=document.querySelector('#photo-large');let photoTrigger;document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{photoTrigger=button;photoLarge.src=button.dataset.photo;photoLarge.alt=button.querySelector('img').alt;document.querySelector('#photo-caption').textContent=button.dataset.caption;photoDialog.showModal()}));document.querySelector('.photo-close').onclick=()=>photoDialog.close();photoDialog.addEventListener('click',e=>{if(e.target===photoDialog){const r=photoDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)photoDialog.close()}});photoDialog.addEventListener('close',()=>photoTrigger?.focus({preventScroll:true}));
